            foil_r, up_r, lo_r = _naca_cambered_pts(rx + 74, ry + 126, 178, alpha_deg=7.5, m=0.055, p=0.38, t=0.135)
            foil_rd = "M " + " L ".join(f"{x:.1f},{y:.1f}" for x, y in foil_r) + " Z"

