                f'    <circle cx="{fcx - 8}" cy="{fcy - 2}" r="2.8" fill="#0f172a"/>',
                f'    <circle cx="{fcx + 8}" cy="{fcy - 2}" r="2.8" fill="#0f172a"/>',
                f'    <circle cx="{fcx - 13}" cy="{fcy + 6}" r="4" fill="{s["cheek"]}" opacity="0.65"/>',
                f'    <circle cx="{fcx + 13}" cy="{fcy + 6}" r="4" fill="{s["cheek"]}" opacity="0.65"/>',
