        # Suction pipe: (116, 184) -> (116, 146) -> (264, 146)
        els.append(_poly([(116, 184), (116, 146), (264, 146)], stroke="#0284c7", sw=4.5))
        els.append(txt(126, 139, "10°C 低压气 (0.95 MPa)", 7.7, BLUE, "middle", weight="700"))
