        els.append(txt(420, 407, "• 避坑指南：除湿模式靠超低风速把贴片空气冻到 4 °C 挤水，风口", 8.2, BODY))
        els.append(txt(420, 424, "  吹出的是极冷细流；盛夏 35 °C 开除湿既慢又不省电，仅适合 24–", 8.2, BODY))
